#define RINGBUF_H

#include <stddef.h>
#include <stdint.h>

/* Fixed-capacity FIFO ring buffer of bytes. Not thread-safe. */
typedef struct ringbuf ringbuf_t;

/* Create a buffer holding up to `capacity` bytes (capacity > 0).
 * Returns NULL on invalid capacity or allocation failure. */
ringbuf_t *rb_create(size_t capacity);

/* Free the buffer. Accepts NULL. */
void rb_destroy(ringbuf_t *rb);

/* Append up to `len` bytes from `data`. Writes as many bytes as fit and
 * returns the number actually written (0 if full or arguments are NULL). */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len);

/* Remove up to `len` bytes into `out`, oldest first. Returns the number
 * actually read (0 if empty or arguments are NULL). */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len);

/* Copy up to `len` oldest bytes into `out` without removing them. */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len);

/* Number of bytes currently stored. */
size_t rb_size(const ringbuf_t *rb);

/* Total capacity given at creation. */
size_t rb_capacity(const ringbuf_t *rb);

/* Discard all content. */
void rb_clear(ringbuf_t *rb);

#endif

input.content:
#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t count;
    size_t head;  /* oldest byte */
    size_t tail;  /* next write position */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;
    if (capacity == 0)
        return NULL;
    rb = calloc(1, sizeof(*rb));
    if (!rb)
        return NULL;
    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->count = 0;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t free_space;
    size_t to_write;

    if (rb == NULL || data == NULL || len == 0)
        return 0;

    free_space = rb->capacity - rb->count;
    to_write = len < free_space ? len : free_space;
    if (to_write == 0)
        return 0;

    /* Write first segment: tail -> end of buffer */
    {
        size_t first = rb->capacity - rb->tail;
        memcpy(rb->buf + rb->tail, data, first < to_write ? first : to_write);
        rb->tail += (first < to_write ? first : to_write);

        if (rb->tail == rb->capacity) {
            /* Wrap around */
            size_t remaining = to_write - first;
            memcpy(rb->buf, data + first, remaining);
            rb->tail = remaining;
        }
    }
    rb->count += to_write;

    return to_write;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t to_read;

    if (rb == NULL || out == NULL || len == 0 || rb->count == 0)
        return 0;

    to_read = len < rb->count ? len : rb->count;

    {
        size_t first = rb->capacity - rb->head;
        memcpy(out, rb->buf + rb->head, first < to_read ? first : to_read);
        out += (first < to_read ? first : to_read);

        if ((rb->head + to_read) > rb->capacity) {
            size_t remaining = to_read - first;
            memcpy(out, rb->buf, remaining);
        }
    }
    rb->head = (rb->head + to_read) % rb->capacity;
    rb->count -= to_read;

    return to_read;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t to_read;

    if (rb == NULL || out == NULL || len == 0 || rb->count == 0)
        return 0;

    to_read = len < rb->count ? len : rb->count;

    {
        size_t first = rb->capacity - rb->head;
        memcpy(out, rb->buf + rb->head, first < to_read ? first : to_read);
        out += (first < to_read ? first : to_read);

        if ((rb->head + to_read) > rb->capacity) {
            size_t remaining = to_read - first;
            memcpy(out, rb->buf, remaining);
        }
    }

    return to_read;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (rb == NULL)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (rb == NULL)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (rb == NULL)
        return;
    rb->count = 0;
    rb->head = 0;
    rb->tail = 0;
}

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    int pass = 1;

    /* Test NULL/NULL ops don't crash */
    rb_destroy(NULL);
    if (rb_size(NULL) != 0 || rb_capacity(NULL) != 0) { pass = 0; }

    /* Create with invalid capacity */
    if (rb_create(0) != NULL) { pass = 0; }

    /* Basic create/destroy */
    ringbuf_t *rb = rb_create(8);
    if (!rb) { printf("FAIL: create\n"); return 1; }
    if (rb_capacity(rb) != 8) { pass = 0; }
    if (rb_size(rb) != 0) { pass = 0; }

    /* Write all bytes */
    unsigned char data[] = {1,2,3,4,5,6,7,8};
    size_t w = rb_write(rb, data, 16);
    if (w != 8) { printf("FAIL: write full capacity wrote=%zu\n", w); pass = 0; }

    /* Write into full buffer */
    data[0] = 99;
    w = rb_write(rb, data, 1);
    if (w != 0) { pass = 0; }

    /* Read should give all 8 bytes */
    unsigned char out[8];
    size_t r = rb_read(rb, out, 8);
    if (r != 8) { printf("FAIL: read count=%zu\n", r); pass = 0; }
    for (int i = 0; i < 8; i++) {
        if (out[i] != (unsigned char)(i + 1)) {
            printf("FAIL: out[%d]=%d expected=%d\n", i, out[i], i + 1);
            pass = 0;
        }
    }

    /* Buffer should be empty */
    if (rb_size(rb) != 0) { pass = 0; }

    /* Ring: write after clear */
    rb_clear(rb);
    unsigned char data2[] = {10, 20, 30};
    w = rb_write(rb, data2, 3);
    if (w != 3 || rb_size(rb) != 3) { pass = 0; }

    /* Peek */
    unsigned char peek[4];
    r = rb_peek(rb, peek, 4);
    if (r != 3 || peek[0] != 10 || peek[1] != 20 || peek[2] != 30) { pass = 0; }

    /* Partial read then write more */
    rb_clear(rb);
    w = rb_write(rb, data2, 3);
    r = rb_read(rb, out, 2);
    if (r != 2 || out[0] != 10 || out[1] != 20) { pass = 0; }

    /* Wrap-around write: fill from tail then add more to wrap */
    rb_clear(rb);
    w = rb_write(rb, data, 4); /* put {1..4} at pos 0-3 */
    r = rb_read(rb, out, 4);   /* remove them, head now == tail == 4 */
    /* Now write past wrap boundary (capacity=8, tail=4) */
    unsigned char data3[] = {50,60,70,80,90}; /* 5 bytes, only 4 fits */
    w = rb_write(rb, data3, 5);
    if (w != 4) { printf("FAIL: wrap write wrote=%zu\n", w); pass = 0; }
    /* Read should give [50,60,70,80] */
    r = rb_read(rb, out, 8);
    if (r != 4 || out[0]!=50||out[1]!=60||out[2]!=70||out[3]!=80) { pass = 0; }

    /* NULL write/read no crash */
    rb_write(NULL, data, 1);
    rb_read(NULL, out, 1);
    rb_peek(NULL, out, 1);

    rb_destroy(rb);

    if (pass) {
        printf("All tests passed.\n");
        return 0;
    } else {
        printf("FAILURES detected.\n");
        return 1;
    }
}

