    /* Read all should be {30,40,50,60,70} */
    r = rb_read(rb, out, 10);
    if (r != 5 || out[0]!=30||out[1]!=40||out[2]!=50||out[3]!=60||out[4]!=70) {
        printf("FAIL wrap read: r=%zu out=[%d,%d,%d,%d,%d]\n",
            r, out[0],out[1],out[2],out[3],out[4]);
        return 1;
