    /* Write full capacity at once (should fit exactly) */
    unsigned char fill[] = {1,2,3,4,5};
    if (rb_write(rb, fill, 5) != 5) { printf("FAIL: exact-full\n"); return 1; }
    /* Now full, write more should give 0 */
    if (rb_write(rb, d2, 4) != 0) { printf("FAIL: no-write-should-fit\n"); return 1; }
    rb_destroy(rb);

    printf("Wrap tests passed.\\n");
    return 0;
}
